package com.wizzadrds.theworldremembers.dream; import com.mojang.serialization.Codec; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class DreamManager extends SavedData {private static final int MAX=256; private final Map<UUID,List<DreamRecord>> dreams=new HashMap<>(); private static final Codec<DreamManager> CODEC=Codec.unboundedMap(com.mojang.serialization.Codec.STRING.xmap(UUID::fromString,UUID::toString),DreamRecord.CODEC.listOf()).xmap(m->{var x=new DreamManager();x.dreams.putAll(m);return x;},x->x.dreams); private static final SavedDataType<DreamManager> TYPE=new SavedDataType<>(net.minecraft.resources.Identifier.fromNamespaceAndPath("the_world_remembers","dreams"),DreamManager::new,CODEC,null); public static DreamManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new DreamManager():l.getDataStorage().computeIfAbsent(TYPE);} public void add(DreamRecord d){var list=dreams.computeIfAbsent(d.sleeper(),k->new ArrayList<>());list.add(d);while(list.size()>MAX/8)list.remove(0);setDirty();} public List<DreamRecord> dreamsOf(UUID sleeper){return List.copyOf(dreams.getOrDefault(sleeper,List.of()));} public Optional<DreamRecord> latest(UUID sleeper){var l=dreams.get(sleeper);return l==null||l.isEmpty()?Optional.empty():Optional.of(l.get(l.size()-1));}}
